import hashlib,html,json,re,shutil,subprocess,sys,zipfile
root=Path(__file__).resolve().parents[2];app=root/'app';base=root/'tester-kit/alpha11-review-1';out=Path(sys.argv[1]).resolve() if len(sys.argv)>1 else root.parent/'NES_Forge_Native_Audio_Library_Review_Kit';candidate=json.loads((root/'CANDIDATE.json').read_text());gate=json.loads((app/'test-results/candidate/Summary.json').read_text());browser=json.loads((root/'reviews/native-audio-library-1/browser/Report.json').read_text());sha=lambda b:hashlib.sha256(b).hexdigest();bundle=app/'mainline/NES_Forge_2.0.0-alpha.11.html'
assert candidate['candidate']=='native-audio-library-1' and gate['status']=='passed' and browser['status']=='passed'
assert sha(bundle.read_bytes())==candidate['htmlSha256']==gate['sha256']==browser['htmlSha256']
