shutil.copytree(base,out);archive=out/'Reference/Historical_Build_Records/RC3';shutil.copytree(base,archive)
overwrite=['NES_Forge.html','START_HERE.html','START_HERE.md','README.md','README.txt','SOURCE_RECORD.json','VERIFICATION.json','CONTENT_INVENTORY.json','DOCUMENTATION_REVIEW.json','REVIEW_REPORT.md','package_files.json','verify_kit.py']
for name in overwrite:
 p=out/name
 if p.exists():shutil.copy2(p,archive/name)
shutil.copy2(bundle,out/'NES_Forge.html');shutil.copy2(app/'docs/NATIVE_AUDIO_LIBRARY.md',out/'Native_Audio_Guide.md');shutil.copy2(root/'CANDIDATE.json',out/'CANDIDATE.json')
style='''*{box-sizing:border-box}body{margin:0;background:#111820;color:#eff3f2;font:16px/1.65 system-ui,sans-serif}main{width:min(1080px,calc(100% - 40px));margin:0 auto;padding:34px 0 60px}header{padding:8px 0 28px;border-bottom:1px solid #354652;font-weight:750;letter-spacing:2px;color:#9ee1c8}h1{font-size:clamp(36px,6vw,62px);line-height:1.08;letter-spacing:-2px;max-width:850px;margin:42px 0 20px}h2{font-size:26px;margin-top:38px;line-height:1.2}h3{font-size:20px}p,li{max-width:900px;color:#b6c7cc}a{color:#9ee1c8}a:hover{color:white}a:focus-visible{outline:3px solid #f6ce72;outline-offset:4px}.actions{display:flex;flex-wrap:wrap;gap:12px;margin:28px 0}.button{display:inline-block;padding:13px 19px;border:1px solid #4b6b67;border-radius:9px;text-decoration:none;font-weight:650;background:#202d38;color:#eff3f2}.primary{background:#9ee1c8;color:#11221d;border-color:#9ee1c8}.card{padding:24px;border:1px solid #354652;border-radius:14px;background:#19232d;margin:24px 0}.kicker{text-transform:uppercase;font-size:12px;letter-spacing:2px;color:#9ee1c8}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px}.grid .card{margin:0}code,pre{font-family:ui-monospace,monospace}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#0b121a;padding:15px;border-radius:7px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{border:1px solid #354652;padding:9px;text-align:left;vertical-align:top}strong{color:#edf9f2}.small{font-size:13px}img{max-width:100%;height:auto}'''
def page(title,body):return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+'</title><style>'+style+'</style></head><body><main><header>NES FORGE / NATIVE AUDIO LIBRARY</header>'+body+'</main></body></html>\n'
guide=(out/'Native_Audio_Guide.md').read_text().replace('mainline/NES_Forge_2.0.0-alpha.11.html','NES_Forge.html');(out/'Native_Audio_Guide.md').write_text(guide)
