with zipfile.ZipFile(zip_path) as z:assert z.testzip() is None
record={'file':str(zip_path),'bytes':zip_path.stat().st_size,'sha256':sha(zip_path.read_bytes()),'files':len(inventory['files'])+1,'applicationSha256':candidate['htmlSha256']};(Path(__file__).parent/'Review_Kit.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps(record))
